SELECT product_id, COALESCE(ROUND(SUM(paid) / NULLIF(SUM(units), 0), 2), 0) AS average_price
FROM Sold
GROUP BY product_id;

SELECT p.project_id, ROUND(AVG(e.experience_years), 2) AS average_years
FROM Project p LEFT JOIN Employee e ON p.employee_id = e.employee_id
GROUP BY p.project_id;

SELECT query_name, ROUND(AVG(rating / position), 2) AS quality,
       ROUND(100.0 * AVG(CASE WHEN rating < 3 THEN 1 ELSE 0 END), 2) AS poor_query_percentage
FROM Queries GROUP BY query_name;

)
SELECT ROUND(100.0 * AVG(CASE WHEN order_date = customer_pref_delivery_date THEN 1 ELSE 0 END), 2)
       AS immediate_percentage
FROM ranked WHERE rn = 1;

)
SELECT ROUND(100 * SUM(immediate) / COUNT(immediate), 2) AS   immediate_percentage
FROM Orders
WHERE number = 1;

)
SELECT visited_on, amount, ROUND(amount / 7.0, 2) AS average_amount
FROM rolled WHERE visited_on >= DATE_ADD(first_day, INTERVAL 6 DAY) ORDER BY visited_on;

)
SELECT ROUND(SUM(tiv_2016), 2) AS tiv_2016 FROM marked
WHERE value_count > 1 AND location_count = 1;

SELECT ROUND(SUM(tiv_2016), 2) AS tiv_2016
FROM Insurance
WHERE pid IN (SELECT pid FROM UniqueCity) AND tiv_2015 IN (SELECT tiv_2015 FROM NonUniqueTIV);
